define(["core/ajax","core/notification"],function(Ajax,Notification){const init=function(flexbookId,chapterId){const list=document.querySelector("[data-region='content-list']");if(!list){return}let dragged=null;list.querySelectorAll(".flexbook-content").forEach(function(block){block.draggable=true;block.addEventListener("dragstart",function(){dragged=block;block.classList.add("is-dragging")});block.addEventListener("dragend",function(){block.classList.remove("is-dragging");dragged=null});block.addEventListener("dragover",function(event){event.preventDefault();if(!dragged||dragged===block){return}const box=block.getBoundingClientRect();list.insertBefore(dragged,event.clientY<box.top+box.height/2?block:block.nextSibling)})});list.addEventListener("drop",function(event){event.preventDefault();const contentIds=Array.from(list.querySelectorAll(".flexbook-content")).map(function(block){return Number(block.dataset.contentId)});Ajax.call([{methodname:"mod_flexbook_reorder_contents",args:{flexbookid:flexbookId,chapterid:chapterId,contentids:contentIds}}])[0].catch(Notification.exception)})};return{init:init}});